export const inlineScript = "\n  function toggleRootingGuide(button) {\n    const card = button.closest('article');\n    const drawer = card.querySelector('.rooting-drawer');\n    const chevron = button.querySelector('.chevron-icon');\n\n    if (drawer.classList.contains('hidden')) {\n      drawer.classList.remove('hidden');\n      if (chevron) chevron.style.transform = 'rotate(180deg)';\n    } else {\n      drawer.classList.add('hidden');\n      if (chevron) chevron.style.transform = 'rotate(0deg)';\n    }\n  }\n\n  function setFilter(btn, filterType) {\n    const buttons = document.querySelectorAll('#filter-bar button');\n    buttons.forEach(b => {\n      b.style.backgroundColor = '#1B2028';\n      b.style.color = '#8F9AA8';\n      b.classList.remove('text-white');\n    });\n\n    btn.style.backgroundColor = '#3478F6';\n    btn.style.color = '#FFFFFF';\n    btn.classList.add('text-white');\n\n    const articles = document.querySelectorAll('article[data-player-type]');\n    articles.forEach(article => {\n      const type = article.getAttribute('data-player-type');\n      if (filterType === 'all' || filterType === 'later') {\n        article.style.display = 'flex';\n      } else if (filterType === 'mine') {\n        article.style.display = (type === 'mine') ? 'flex' : 'none';\n      } else if (filterType === 'opponents') {\n        article.style.display = (type === 'opponents') ? 'flex' : 'none';\n      } else if (filterType === 'live') {\n        article.style.display = 'none';\n      }\n    });\n  }\n";
